program SDAPReceiver;
  driver_exception = sdap;

  procedure OnActivate();
  var
    event : string;
  begin
    loop
      core.DriverQueryProc( 'sdap', 'event get', &event );
      if event = '' then
        exit;
      end;

      ... processing of errors and events

    end; (* loop *)
  end_procedure;

end_program;
